const startDeprovisionHostedGateway = `-- name: StartDeprovisionHostedGateway :one
UPDATE pc.hosted_gateways
SET state = CASE WHEN host_id IS NULL THEN 'DEPROVISIONED' ELSE 'DEPROVISIONING' END,
    deprovisioned_at = CASE WHEN host_id IS NULL THEN now() END,
    token_sealed = NULL, updated_at = now()
WHERE org_id = $1 AND id = $2 AND state NOT IN ('DEPROVISIONING', 'DEPROVISIONED', 'FAILED')
RETURNING org_id, id, slug, state, gateway_id, host_id, milli_cpus, memory_mib, pids, token_sealed, token_pulled_at, enrollment_id, enrolled_cert_id, version, target_version, failure, created_by, created_at, updated_at, deprovisioned_at
`

// Marks the org's hosted gateway for stopping; the caller has revoked its
// gateway in the same transaction first (HR-503).
func (q *Queries) StartDeprovisionHostedGateway(ctx context.Context, orgID ids.OrgID, iD ids.UUID) (PcHostedGateway, error) {
	row := q.db.QueryRow(ctx, startDeprovisionHostedGateway, orgID, iD)
	var i PcHostedGateway
	err := row.Scan(
		&i.OrgID,
		&i.ID,
		&i.Slug,
		&i.State,
		&i.GatewayID,
		&i.HostID,
		&i.MilliCpus,
		&i.MemoryMib,
		&i.Pids,
		&i.TokenSealed,
		&i.TokenPulledAt,
		&i.EnrollmentID,
		&i.EnrolledCertID,
		&i.Version,
		&i.TargetVersion,
		&i.Failure,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeprovisionedAt,
	)
	return i, err
}

